<?php
require_once dirname(__DIR__,3).'/bootstrap.php';$allowedRoles=[ROLE_HOUSEPARENT];require APP_ROOT.'/app/middleware/RoleMiddleware.php';use App\Services\StudentService;use PhpOffice\PhpSpreadsheet\IOFactory;
$houseId=current_user()['houseId']??null;$errors=[];$success=0;if(isset($_GET['download_template'])){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="houseparent_student_import_template.csv"');$out=fopen('php://output','w');fputcsv($out,['FirstName','LastName','Email','Phone','AdmissionNo','Course','Level']);fputcsv($out,['Jane','Doe','jane@example.com','0800000000','ADM001','Course','Year 1']);fclose($out);exit;}if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='import_students'&&!empty($_FILES['students_file'])){$file=$_FILES['students_file'];$extension=strtolower(pathinfo($file['name']??'',PATHINFO_EXTENSION));if($file['error']!==UPLOAD_ERR_OK||!in_array($extension,['csv','xlsx'],true)){$errors[]='Upload a valid CSV or XLSX file.';}else{try{$rows=IOFactory::load($file['tmp_name'])->getActiveSheet()->toArray(null,true,true,false);$header=array_map(fn($v)=>strtolower(preg_replace('/[^a-z0-9]/i','',(string)$v)),array_shift($rows)?:[]);$map=[];foreach($header as $i=>$name)$map[$name]=$i;foreach(array_slice($rows,0,1000) as $row){$value=fn($name,$fallback=-1)=>$row[$map[strtolower(preg_replace('/[^a-z0-9]/i','',$name))]??$fallback]??'';$first=sanitize($value('firstname',0));$admission=sanitize($value('admissionno',4));if($first===''||$admission==='')continue;StudentService::create(['firstName'=>$first,'lastName'=>sanitize($value('lastname',1)),'email'=>sanitize($value('email',2)),'phone'=>sanitize($value('phone',3)),'admissionNo'=>$admission,'course'=>sanitize($value('course',5)),'level'=>sanitize($value('level',6)),'houseId'=>$houseId,'status'=>'active']);$success++;}flash('success',"Imported {$success} student(s) into your house.");redirect(url('views/houseparent/students/bulk-import.php'));}catch(Throwable $e){$errors[]='Import failed: '.$e->getMessage();}}}$pageTitle='Import Houseparent Students';$navItems=[['icon'=>'bi-mortarboard','label'=>'Students','href'=>url('views/houseparent/students/index.php')],['icon'=>'bi-upload','label'=>'Import Students','href'=>url('views/houseparent/students/bulk-import.php'),'active'=>true]];require APP_ROOT.'/app/views/components/header.php';require APP_ROOT.'/app/views/components/sidebar.php';?>
<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><?php require APP_ROOT.'/app/views/components/alerts.php';?><div class="content-wrapper"><div class="card stat-card p-4" style="max-width:760px"><h5 class="mb-3">Import Students</h5><?php foreach($errors as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><form method="POST" enctype="multipart/form-data"><input type="hidden" name="action" value="import_students"><label class="form-label">CSV or XLSX file</label><input type="file" name="students_file" class="form-control mb-3" accept=".csv,.xlsx" required><p class="small text-muted">Headers: FirstName, LastName, Email, Phone, AdmissionNo, Course, Level. Maximum 1,000 rows. All imported students are assigned to your house.</p><button class="btn btn-primary">Upload and import</button> <a class="btn btn-outline-secondary" href="<?=url('views/houseparent/students/bulk-import.php?download_template=1')?>">Download template</a></form></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php';?>